-- ===================================================================
-- 0012 — IN-APP NOTIFICATIONS (Phase 1)
--
-- Per-recipient, in-app notifications generated by the database from
-- meaningful state changes in existing modules. No email, SMS, push,
-- scheduler or chat.
--
--   notifications (id)                                   PK
--     recipient_id → profiles (id)   ON DELETE CASCADE
--     actor_id     → profiles (id)   ON DELETE SET NULL
--     unique (recipient_id, event_key)                   de-duplication
--
-- ACCESS: each user reads only their own rows (RLS). Nobody may insert,
-- update or delete through the API; read state changes only through
-- mark_notification_read() / mark_all_notifications_read(). A guard
-- trigger keeps every column except read_at immutable for every
-- writer. Notifications are created only by the internal
-- notify_recipients() function, called from AFTER triggers.
--
-- EVENTS (AFTER triggers, meaningful transitions only):
--   classes                 created (today or later), updated
--                           (date/time/Teams link), cancelled
--   class_assignments       published (first publication)
--   assignment_submissions  received, resubmitted, returned
--   tests                   published, closed (manual close)
--   completion_records      recommended, approved, rejected
--   certificates            issued, revoked
--
-- SAFETY: every notification path catches its own exceptions, so a
-- notification failure can never roll back the original operation.
-- Notification text never contains scores, attendance, answer keys,
-- verification codes, revocation reasons, notes or email addresses;
-- links are internal routes only (no query strings).
--
-- 0012 does NOT alter any existing table, column, policy, function or
-- migration; it only attaches new AFTER triggers to existing tables.
-- Runs as ONE transaction. Depends on 0001–0011. REVIEW BEFORE RUNNING.
-- ===================================================================

begin;

-- -------------------------------------------------------------------
-- 0. Preflight — abort unless 0001–0011 are in place and 0012 is not.
-- -------------------------------------------------------------------
do $$
begin
  if to_regclass('public.profiles') is null
     or to_regclass('public.students') is null
     or to_regclass('public.batches') is null
     or to_regclass('public.batch_students') is null
     or to_regclass('public.classes') is null
     or to_regclass('public.class_assignments') is null
     or to_regclass('public.assignment_submissions') is null
     or to_regclass('public.tests') is null
     or to_regclass('public.test_attempts') is null
     or to_regclass('public.completion_records') is null
     or to_regclass('public.certificates') is null then
    raise exception 'Preflight failed: 0001–0011 objects are missing.';
  end if;

  if to_regclass('public.notifications') is not null
     or to_regtype('public.notification_type') is not null
     or to_regtype('public.notification_entity') is not null then
    raise exception 'Preflight failed: 0012 already applied?';
  end if;
end
$$;

-- -------------------------------------------------------------------
-- 1. Types
-- -------------------------------------------------------------------
create type public.notification_type as enum (
  'class_scheduled',
  'class_updated',
  'class_cancelled',
  'assignment_published',
  'submission_received',
  'submission_updated',
  'submission_returned',
  'test_published',
  'test_closed',
  'completion_recommended',
  'completion_approved',
  'completion_rejected',
  'certificate_issued',
  'certificate_revoked'
);

create type public.notification_entity as enum (
  'class',
  'assignment',
  'submission',
  'test',
  'completion',
  'certificate'
);

-- -------------------------------------------------------------------
-- 2. Table
-- -------------------------------------------------------------------
create table public.notifications (
  id                   uuid                        not null default gen_random_uuid(),
  recipient_id         uuid                        not null references public.profiles (id) on delete cascade,
  type                 public.notification_type    not null,
  title                text                        not null,
  body                 text                        not null,
  link                 text                        null,
  related_entity_type  public.notification_entity  null,
  related_entity_id    uuid                        null,
  event_key            text                        not null,
  actor_id             uuid                        null references public.profiles (id) on delete set null,
  created_at           timestamptz                 not null default now(),
  read_at              timestamptz                 null,

  constraint notifications_pkey primary key (id),
  -- One notification per recipient per event (see the event keys below).
  constraint notifications_recipient_event_key unique (recipient_id, event_key),
  constraint notifications_title_ok   check (char_length(btrim(title)) between 1 and 80),
  constraint notifications_body_ok    check (char_length(btrim(body)) between 1 and 280),
  -- Internal application routes only: no protocol, host, query string or fragment.
  constraint notifications_link_ok    check (link is null or link ~ '^/(admin|trainer|student)/[A-Za-z0-9/_.-]{0,180}$'),
  constraint notifications_event_key_ok check (char_length(event_key) between 1 and 200),
  constraint notifications_entity_ok  check ((related_entity_type is null) = (related_entity_id is null)),
  constraint notifications_read_ok    check (read_at is null or read_at >= created_at)
);

create index notifications_recipient_created_idx on public.notifications (recipient_id, created_at desc);
create index notifications_recipient_unread_idx  on public.notifications (recipient_id) where read_at is null;

-- -------------------------------------------------------------------
-- 3. Guard — content is immutable for every writer; read_at may only
--    go from NULL to a timestamp. (actor_id may only be cleared by the
--    ON DELETE SET NULL action.) Privileged deletes stay possible for
--    future retention clean-up.
-- -------------------------------------------------------------------
create function public.notifications_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    new.created_at := now();
    new.read_at := null;
    return new;
  end if;

  if (new.id, new.recipient_id, new.type, new.title, new.body, new.link, new.related_entity_type,
      new.related_entity_id, new.event_key, new.created_at)
     is distinct from
     (old.id, old.recipient_id, old.type, old.title, old.body, old.link, old.related_entity_type,
      old.related_entity_id, old.event_key, old.created_at) then
    raise exception 'Notification content cannot be changed.' using errcode = '42501';
  end if;
  if new.actor_id is distinct from old.actor_id and new.actor_id is not null then
    raise exception 'Notification content cannot be changed.' using errcode = '42501';
  end if;
  if old.read_at is not null and new.read_at is distinct from old.read_at then
    raise exception 'A notification that has been read cannot be changed.' using errcode = '42501';
  end if;
  return new;
end;
$$;
revoke all on function public.notifications_guard() from public, anon, authenticated, service_role;

create trigger notifications_guard
  before insert or update on public.notifications
  for each row execute function public.notifications_guard();

-- -------------------------------------------------------------------
-- 4. Privileges + RLS — recipients read their own rows; no API writes.
-- -------------------------------------------------------------------
alter table public.notifications enable row level security;

revoke all on table public.notifications from anon, authenticated, service_role;
grant select on table public.notifications to authenticated, service_role;

create policy notifications_recipient_select
  on public.notifications for select to authenticated
  using (recipient_id = (select auth.uid()));

-- -------------------------------------------------------------------
-- 5. User functions (identity from auth.uid(); no recipient argument)
-- -------------------------------------------------------------------

-- Latest notifications of the signed-in user (at most 50). Runs with
-- the caller's rights, so RLS applies as well.
create function public.my_notifications(p_limit integer default 50)
returns table (
  id                   uuid,
  type                 public.notification_type,
  title                text,
  body                 text,
  link                 text,
  related_entity_type  public.notification_entity,
  created_at           timestamptz,
  read_at              timestamptz
)
language plpgsql
stable
set search_path = ''
as $$
begin
  if auth.uid() is null then
    raise exception 'You need to be signed in.' using errcode = '42501';
  end if;
  return query
    select n.id, n.type, n.title, n.body, n.link, n.related_entity_type, n.created_at, n.read_at
      from public.notifications n
     where n.recipient_id = auth.uid()
     order by n.created_at desc, n.id desc
     limit least(greatest(coalesce(p_limit, 50), 1), 50);
end;
$$;

create function public.my_unread_notification_count()
returns integer
language plpgsql
stable
set search_path = ''
as $$
begin
  if auth.uid() is null then
    raise exception 'You need to be signed in.' using errcode = '42501';
  end if;
  return (select count(*)::integer from public.notifications n where n.recipient_id = auth.uid() and n.read_at is null);
end;
$$;

-- Marks one of the caller's own unread notifications as read. Returns
-- false for someone else's id, an unknown id or an already-read one.
create function public.mark_notification_read(p_notification_id uuid)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.uid() is null then
    raise exception 'You need to be signed in.' using errcode = '42501';
  end if;
  update public.notifications n
     set read_at = now()
   where n.id = p_notification_id and n.recipient_id = auth.uid() and n.read_at is null;
  return found;
end;
$$;

create function public.mark_all_notifications_read()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_count integer;
begin
  if auth.uid() is null then
    raise exception 'You need to be signed in.' using errcode = '42501';
  end if;
  update public.notifications n
     set read_at = now()
   where n.recipient_id = auth.uid() and n.read_at is null;
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

revoke all on function public.my_notifications(integer)        from public, anon, service_role;
revoke all on function public.my_unread_notification_count()   from public, anon, service_role;
revoke all on function public.mark_notification_read(uuid)     from public, anon, service_role;
revoke all on function public.mark_all_notifications_read()    from public, anon, service_role;
grant execute on function public.my_notifications(integer)      to authenticated;
grant execute on function public.my_unread_notification_count() to authenticated;
grant execute on function public.mark_notification_read(uuid)   to authenticated;
grant execute on function public.mark_all_notifications_read()  to authenticated;

-- -------------------------------------------------------------------
-- 6. Internal notification helpers (no user execute privilege)
-- -------------------------------------------------------------------

-- Inserts one notification per distinct recipient (skipping the actor
-- unless p_skip_actor is false). Duplicates by (recipient, event_key)
-- are ignored. NEVER raises: any failure is reported as a WARNING and
-- only this notification is rolled back, never the caller's operation.
create function public.notify_recipients(
  p_recipients   uuid[],
  p_type         public.notification_type,
  p_title        text,
  p_body         text,
  p_link         text,
  p_entity_type  public.notification_entity,
  p_entity_id    uuid,
  p_event_key    text,
  p_skip_actor   boolean default true
)
returns void
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_actor uuid := auth.uid();
begin
  begin
    if p_recipients is null or cardinality(p_recipients) = 0 then
      return;
    end if;
    insert into public.notifications (recipient_id, type, title, body, link, related_entity_type, related_entity_id, event_key, actor_id)
    select r, p_type, left(btrim(p_title), 80), left(btrim(p_body), 280), p_link, p_entity_type, p_entity_id, left(p_event_key, 200), v_actor
      from (select distinct unnest(p_recipients) as r) x
     where x.r is not null
       and (not p_skip_actor or v_actor is null or x.r <> v_actor)
    on conflict (recipient_id, event_key) do nothing;
  exception when others then
    raise warning 'notify_recipients(%) skipped: % %', p_type, sqlstate, sqlerrm;
  end;
end;
$$;

-- Enrolled (not withdrawn/completed), non-inactive students of a batch.
create function public.notification_batch_students(p_batch_id uuid)
returns uuid[]
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(array_agg(bs.student_id), '{}')
    from public.batch_students bs
    join public.students s on s.id = bs.student_id
   where bs.batch_id = p_batch_id
     and bs.enrollment_status = 'enrolled'
     and s.status <> 'inactive';
$$;

-- The batch's current trainer (NULL when none is assigned).
create function public.notification_batch_trainer(p_batch_id uuid)
returns uuid
language sql
stable
security definer
set search_path = ''
as $$
  select b.trainer_id from public.batches b where b.id = p_batch_id;
$$;

create function public.notification_super_admins()
returns uuid[]
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(array_agg(p.id), '{}') from public.profiles p where p.role = 'super_admin';
$$;

-- Today in India time (class dates are India-local dates).
create function public.notification_today()
returns date
language sql
stable
set search_path = ''
as $$
  select (now() at time zone 'Asia/Kolkata')::date;
$$;

-- Stable per-transaction version for events that may legitimately repeat.
create function public.notification_txn_version()
returns text
language sql
stable
set search_path = ''
as $$
  select to_char(extract(epoch from now()), 'FM9999999999999.999999');
$$;

revoke all on function public.notify_recipients(uuid[], public.notification_type, text, text, text, public.notification_entity, uuid, text, boolean)
  from public, anon, authenticated, service_role;
revoke all on function public.notification_batch_students(uuid) from public, anon, authenticated, service_role;
revoke all on function public.notification_batch_trainer(uuid)  from public, anon, authenticated, service_role;
revoke all on function public.notification_super_admins()       from public, anon, authenticated, service_role;
revoke all on function public.notification_today()              from public, anon, authenticated, service_role;
revoke all on function public.notification_txn_version()        from public, anon, authenticated, service_role;

-- -------------------------------------------------------------------
-- 7. Event triggers (AFTER; meaningful transitions only). Each trigger
--    function also catches its own exceptions.
-- -------------------------------------------------------------------

-- a) Classes: scheduled (today or later), updated, cancelled.
create function public.notify_class_event()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_batch_code text;
  v_when       text;
  v_students   uuid[];
begin
  begin
    select b.batch_code into v_batch_code from public.batches b where b.id = new.batch_id;
    v_when := to_char(new.class_date, 'DD Mon YYYY') || ' at ' || to_char(new.start_time, 'HH24:MI') || ' (India time)';
    v_students := public.notification_batch_students(new.batch_id);

    if tg_op = 'INSERT' then
      if new.status in ('scheduled', 'live') and new.class_date >= public.notification_today() then
        perform public.notify_recipients(
          v_students, 'class_scheduled', 'New class scheduled',
          '"' || left(new.title, 120) || '" on ' || v_when || ' — ' || coalesce(v_batch_code, ''),
          '/student/classes/' || new.id, 'class', new.id,
          'class_scheduled:' || new.id);
      end if;

    elsif new.status = 'cancelled' and old.status is distinct from 'cancelled' then
      perform public.notify_recipients(
        v_students, 'class_cancelled', 'Class cancelled',
        '"' || left(new.title, 120) || '" on ' || to_char(new.class_date, 'DD Mon YYYY') || ' has been cancelled.',
        '/student/classes/' || new.id, 'class', new.id,
        'class_cancelled:' || new.id);
      perform public.notify_recipients(
        array[public.notification_batch_trainer(new.batch_id)], 'class_cancelled', 'Class cancelled',
        '"' || left(new.title, 120) || '" on ' || to_char(new.class_date, 'DD Mon YYYY') || ' has been cancelled.',
        '/trainer/classes/' || new.id, 'class', new.id,
        'class_cancelled:' || new.id);

    elsif new.status <> 'cancelled'
          and new.class_date >= public.notification_today()
          and (new.class_date, new.start_time, new.end_time, new.teams_meeting_url)
              is distinct from (old.class_date, old.start_time, old.end_time, old.teams_meeting_url) then
      perform public.notify_recipients(
        v_students, 'class_updated', 'Class updated',
        'The date, time or Teams link for "' || left(new.title, 120) || '" has changed. Now ' || v_when || '.',
        '/student/classes/' || new.id, 'class', new.id,
        'class_updated:' || new.id || ':' || public.notification_txn_version());
    end if;
  exception when others then
    raise warning 'notify_class_event skipped: % %', sqlstate, sqlerrm;
  end;
  return null;
end;
$$;

create trigger notify_class_insert
  after insert on public.classes
  for each row execute function public.notify_class_event();

create trigger notify_class_update
  after update on public.classes
  for each row
  when ((old.class_date, old.start_time, old.end_time, old.teams_meeting_url, old.status)
        is distinct from (new.class_date, new.start_time, new.end_time, new.teams_meeting_url, new.status))
  execute function public.notify_class_event();

-- b) Assignments: first publication (inserted as published, or draft → published).
create function public.notify_assignment_published()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_class_title text;
begin
  begin
    select c.title into v_class_title from public.classes c where c.id = new.class_id;
    perform public.notify_recipients(
      public.notification_batch_students(new.batch_id), 'assignment_published', 'New assignment',
      '"' || left(new.title, 120) || '" for ' || left(coalesce(v_class_title, 'your class'), 120) || '.',
      '/student/classes/' || new.class_id, 'assignment', new.id,
      'assignment_published:' || new.id);
  exception when others then
    raise warning 'notify_assignment_published skipped: % %', sqlstate, sqlerrm;
  end;
  return null;
end;
$$;

create trigger notify_assignment_insert
  after insert on public.class_assignments
  for each row when (new.status = 'published')
  execute function public.notify_assignment_published();

create trigger notify_assignment_update
  after update on public.class_assignments
  for each row when (old.status = 'draft' and new.status = 'published')
  execute function public.notify_assignment_published();

-- c) Submissions: received and resubmitted (→ batch trainer), returned (→ student).
create function public.notify_submission_event()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_assignment  text;
  v_class_id    uuid;
  v_student     text;
begin
  begin
    select ca.title, ca.class_id into v_assignment, v_class_id
      from public.class_assignments ca where ca.id = new.assignment_id;
    select s.full_name into v_student from public.students s where s.id = new.student_id;

    if tg_op = 'INSERT' then
      perform public.notify_recipients(
        array[public.notification_batch_trainer(new.batch_id)], 'submission_received', 'New submission',
        left(coalesce(v_student, 'A student'), 120) || ' submitted "' || left(coalesce(v_assignment, 'an assignment'), 120) || '".',
        '/trainer/classes/' || v_class_id, 'submission', new.assignment_id,
        'submission_received:' || new.assignment_id || ':' || new.student_id);

    elsif old.status = 'submitted' and new.status = 'returned' then
      perform public.notify_recipients(
        array[new.student_id], 'submission_returned', 'Assignment returned',
        '"' || left(coalesce(v_assignment, 'Your assignment'), 120) || '" has been reviewed.',
        '/student/classes/' || v_class_id, 'submission', new.assignment_id,
        'submission_returned:' || new.assignment_id || ':' || new.student_id || ':'
          || coalesce(to_char(extract(epoch from new.reviewed_at), 'FM9999999999999.999999'), public.notification_txn_version()));

    elsif old.status = 'submitted' and new.status = 'submitted' and new.submitted_at is distinct from old.submitted_at then
      perform public.notify_recipients(
        array[public.notification_batch_trainer(new.batch_id)], 'submission_updated', 'Submission updated',
        left(coalesce(v_student, 'A student'), 120) || ' resubmitted "' || left(coalesce(v_assignment, 'an assignment'), 120) || '".',
        '/trainer/classes/' || v_class_id, 'submission', new.assignment_id,
        'submission_updated:' || new.assignment_id || ':' || new.student_id || ':'
          || to_char(extract(epoch from new.submitted_at), 'FM9999999999999.999999'));
    end if;
  exception when others then
    raise warning 'notify_submission_event skipped: % %', sqlstate, sqlerrm;
  end;
  return null;
end;
$$;

create trigger notify_submission_insert
  after insert on public.assignment_submissions
  for each row execute function public.notify_submission_event();

create trigger notify_submission_update
  after update on public.assignment_submissions
  for each row
  when (old.status is distinct from new.status or old.submitted_at is distinct from new.submitted_at)
  execute function public.notify_submission_event();

-- d) Tests: published (draft → scheduled/active); closed (scheduled/active → closed, manual close).
create function public.notify_test_event()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_class_title text;
  v_attempters  uuid[];
begin
  begin
    select c.title into v_class_title from public.classes c where c.id = new.class_id;

    if old.status = 'draft' and new.status in ('scheduled', 'active') then
      perform public.notify_recipients(
        public.notification_batch_students(new.batch_id), 'test_published', 'Test available',
        '"' || left(new.title, 120) || '" for ' || left(coalesce(v_class_title, 'your class'), 120) || '.',
        '/student/tests/' || new.id, 'test', new.id,
        'test_published:' || new.id);

    elsif old.status in ('scheduled', 'active') and new.status = 'closed' then
      -- Students who attempted the test and are still enrolled (or completed).
      select coalesce(array_agg(distinct a.student_id), '{}') into v_attempters
        from public.test_attempts a
        join public.batch_students bs on bs.batch_id = a.batch_id and bs.student_id = a.student_id
        join public.students s on s.id = a.student_id
       where a.test_id = new.id
         and bs.enrollment_status in ('enrolled', 'completed')
         and s.status <> 'inactive';
      perform public.notify_recipients(
        v_attempters, 'test_closed', 'Test closed',
        '"' || left(new.title, 120) || '" has closed. Your result is now available.',
        '/student/tests/' || new.id, 'test', new.id,
        'test_closed:' || new.id || ':' || public.notification_txn_version());
    end if;
  exception when others then
    raise warning 'notify_test_event skipped: % %', sqlstate, sqlerrm;
  end;
  return null;
end;
$$;

create trigger notify_test_status
  after update on public.tests
  for each row when (old.status is distinct from new.status)
  execute function public.notify_test_event();

-- e) Completion: recommended (→ Super Admins), approved / rejected (→ student + batch trainer).
create function public.notify_completion_event()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_student     text;
  v_batch_code  text;
  v_course      text;
  v_version     text;
begin
  begin
    select s.full_name into v_student from public.students s where s.id = new.student_id;
    select b.batch_code, co.title into v_batch_code, v_course
      from public.batches b join public.courses co on co.id = b.course_id
     where b.id = new.batch_id;

    if new.status = 'recommended' then
      v_version := to_char(extract(epoch from new.recommended_at), 'FM9999999999999.999999');
      perform public.notify_recipients(
        public.notification_super_admins(), 'completion_recommended', 'Completion awaiting approval',
        left(coalesce(v_student, 'A student'), 120) || ' was recommended for completion of ' || coalesce(v_batch_code, 'a batch') || '.',
        '/admin/certificates/' || new.batch_id, 'completion', new.id,
        'completion_recommended:' || new.id || ':' || v_version);

    elsif new.status in ('approved', 'rejected') then
      v_version := coalesce(to_char(extract(epoch from new.decided_at), 'FM9999999999999.999999'), public.notification_txn_version());
      if new.status = 'approved' then
        perform public.notify_recipients(
          array[new.student_id], 'completion_approved', 'Completion approved',
          'Your completion of ' || left(coalesce(v_course, 'the course'), 120) || ' (' || coalesce(v_batch_code, '') || ') was approved.',
          '/student/certificates', 'completion', new.id,
          'completion_approved:' || new.id || ':' || v_version);
        perform public.notify_recipients(
          array[public.notification_batch_trainer(new.batch_id)], 'completion_approved', 'Completion approved',
          left(coalesce(v_student, 'A student'), 120) || ' — completion approved for ' || coalesce(v_batch_code, 'the batch') || '.',
          '/trainer/certificates/' || new.batch_id, 'completion', new.id,
          'completion_approved:' || new.id || ':' || v_version);
      else
        perform public.notify_recipients(
          array[new.student_id], 'completion_rejected', 'Completion not approved',
          'Your completion for ' || coalesce(v_batch_code, 'the batch') || ' was not approved. See details.',
          '/student/certificates', 'completion', new.id,
          'completion_rejected:' || new.id || ':' || v_version);
        perform public.notify_recipients(
          array[public.notification_batch_trainer(new.batch_id)], 'completion_rejected', 'Completion not approved',
          left(coalesce(v_student, 'A student'), 120) || ' — completion not approved for ' || coalesce(v_batch_code, 'the batch') || '.',
          '/trainer/certificates/' || new.batch_id, 'completion', new.id,
          'completion_rejected:' || new.id || ':' || v_version);
      end if;
    end if;
  exception when others then
    raise warning 'notify_completion_event skipped: % %', sqlstate, sqlerrm;
  end;
  return null;
end;
$$;

create trigger notify_completion_insert
  after insert on public.completion_records
  for each row execute function public.notify_completion_event();

create trigger notify_completion_update
  after update on public.completion_records
  for each row when (old.status is distinct from new.status)
  execute function public.notify_completion_event();

-- f) Certificates: issued, revoked (→ the student).
create function public.notify_certificate_event()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  begin
    if tg_op = 'INSERT' then
      perform public.notify_recipients(
        array[new.student_id], 'certificate_issued', 'Certificate issued',
        'Your ' || left(new.course_title, 120) || ' certificate is ready.',
        '/student/certificates/' || new.certificate_number, 'certificate', new.id,
        'certificate_issued:' || new.id);
    elsif old.status = 'issued' and new.status = 'revoked' then
      perform public.notify_recipients(
        array[new.student_id], 'certificate_revoked', 'Certificate revoked',
        'Your certificate ' || new.certificate_number || ' has been revoked.',
        '/student/certificates', 'certificate', new.id,
        'certificate_revoked:' || new.id);
    end if;
  exception when others then
    raise warning 'notify_certificate_event skipped: % %', sqlstate, sqlerrm;
  end;
  return null;
end;
$$;

create trigger notify_certificate_insert
  after insert on public.certificates
  for each row execute function public.notify_certificate_event();

create trigger notify_certificate_update
  after update on public.certificates
  for each row when (old.status is distinct from new.status)
  execute function public.notify_certificate_event();

revoke all on function public.notify_class_event()          from public, anon, authenticated, service_role;
revoke all on function public.notify_assignment_published() from public, anon, authenticated, service_role;
revoke all on function public.notify_submission_event()     from public, anon, authenticated, service_role;
revoke all on function public.notify_test_event()           from public, anon, authenticated, service_role;
revoke all on function public.notify_completion_event()     from public, anon, authenticated, service_role;
revoke all on function public.notify_certificate_event()    from public, anon, authenticated, service_role;

commit;
